function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; var t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function nzFade(t){ return t*t*t*(t*(t*6-15)+10); }
function nzLerp(a,b,t){ return a+(b-a)*t; }
function nzGrad(h,x,y){ var u=(h&1)?-x:x, v=(h&2)?-y:y; return u+v; }
function nzPerm(seed){
  var rnd=mulberry32(seed||1), p=[]; for(var i=0;i<256;i++) p[i]=i;
  for(var i=255;i>0;i--){ var j=Math.floor(rnd()*(i+1)); var t=p[i]; p[i]=p[j]; p[j]=t; }
  var perm=[]; for(var i=0;i<512;i++) perm[i]=p[i&255]; return perm;
}
function nzPerlin2D(x,y,perm){
  var X=Math.floor(x)&255, Y=Math.floor(y)&255, xf=x-Math.floor(x), yf=y-Math.floor(y);
  var u=nzFade(xf), v=nzFade(yf);
  var aa=perm[perm[X]+Y], ab=perm[perm[X]+Y+1], ba=perm[perm[X+1]+Y], bb=perm[perm[X+1]+Y+1];
  var x1=nzLerp(nzGrad(aa,xf,yf), nzGrad(ba,xf-1,yf), u);
  var x2=nzLerp(nzGrad(ab,xf,yf-1), nzGrad(bb,xf-1,yf-1), u);
  return (nzLerp(x1,x2,v)+1)/2;
}
function nzField(w,h,scale,seed){
  var perm=nzPerm(seed), f=[];
  for(var y=0;y<h;y++){ var row=[]; for(var x=0;x<w;x++){ row.push(nzPerlin2D(x*scale, y*scale, perm)); } f.push(row); }
  return f;
}
function nzRamp(v, kind){
  if(kind==='terrain'){
    // water -> grass -> rock -> snow
    if(v<0.35) return [30,70,140];
    if(v<0.5) return [60,120,200];
    if(v<0.65) return [70,150,70];
    if(v<0.8) return [120,140,80];
    return [220,220,230];
